#include <stdio.h>

typedef void (*sort_strategy)(int*, int);

void bubble_sort(int arr[], int n) {
    for (int i = 0; i < n-1; i++)
        for (int j = 0; j < n-i-1; j++)
            if (arr[j] > arr[j+1]) { int t=arr[j]; arr[j]=arr[j+1]; arr[j+1]=t; }
}

void insertion_sort(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        int key = arr[i], j = i-1;
        while (j >= 0 && arr[j] > key) { arr[j+1] = arr[j]; j--; }
        arr[j+1] = key;
    }
}

void sort_and_print(sort_strategy s, int arr[], int n) {
    s(arr, n);
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");
}

int main() {
    int arr1[] = {5, 2, 9, 1, 5};
    int arr2[] = {5, 2, 9, 1, 5};
    sort_and_print(bubble_sort, arr1, 5);
    sort_and_print(insertion_sort, arr2, 5);
    return 0;
}
